mapper.select:
SELECT om.CHNR as chassisNo, om.SERIE as serie, om.ORDERNUMBER as ordernumber, om.BUILD as buildWeek, om.SPEC as specWeek, vda.COUNTRY_OF_OPERATION as market, '-EU' as masterMarket, om.CUSTOMER_ADAP as sNoteNo, CASE WHEN om.CUSTOMER_ADAP IS NOT NULL AND om.CUSTOMER_ADAP != '' THEN 'The S-Notes above can affect homologation documents.' ELSE NULL END as sNoteMessage, tire.LOAD_INDEX as loadIndex, 'View Rules' as analyzeRules, cha.ACT as modifyDocLink, 'VIN_PLATE_TEMPLATE_V1' as usingTemplate, CASE WHEN admod.VARIABLE IS NOT NULL THEN GROUP_CONCAT(CONCAT('AD Change. Modifying:', admod.VARIABLE) SEPARATOR '; ') ELSE NULL END as replacingParameters, CONCAT('/downloads/vin_plate_', om.CHNR, '.trf') as generatedDocument, DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s') as date, 'v1.0.0' as hdocVersion FROM HDOC_REC_DATA_VDA_GENERAL vda INNER JOIN HDOC_REC_DATA_OM om ON vda.SERIE = om.SERIE AND vda.CHNR = om.CHNR LEFT JOIN HDOC_REC_DATA_KOLA_TIRE_MASTER tire ON vda.TRANS_TS = tire.TRANS_TS LEFT JOIN HDOC_ADCA_CHANGE cha ON vda.SERIE = cha.SERIE AND vda.CHNR = cha.CHNR LEFT JOIN HDOC_ADCA_MODIFICATION admod ON vda.SERIE = admod.SERIE AND vda.CHNR = admod.CHNO AND admod.STA = '0' WHERE vda.CHNR = #{chassisNo}
AND vda.SERIE = #{chassisSeries}
AND admod.STA = '0' GROUP BY om.SERIE, om.ORDERNUMBER, om.BUILD, om.SPEC, vda.COUNTRY_OF_OPERATION, om.CUSTOMER_ADAP, tire.LOAD_INDEX, cha.ACT, admod.VARIABLE LIMIT 1
